// Compute a per-meter statistical baseline and flag anomalies: spikes, drops,
// suspected leakage (continuous flow during configured off-hours), and stuck
// meters (near-zero variance despite an active baseline). Expects the API
// response shape: { meters: [ { meterId, address, readings: [ { timestamp, value }, ... ] } ] }
const config = $('Set Configuration Parameters').item.json;
const response = $input.item.json;
const meters = response.meters || [];

const output = meters.map(meter => {
  const readings = meter.readings || [];
  const values = readings.map(r => r.value);

  if (values.length < 3) {
    return { json: { ...config, meterId: meter.meterId, meterAddress: meter.address || meter.location || 'unknown', anomalyDetected: false, anomalyScore: 0, reason: 'insufficient-data' } };
  }

  const current = values[values.length - 1];
  const history = values.slice(0, -1);

  const mean = history.reduce((a, b) => a + b, 0) / history.length;
  const variance = history.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / history.length;
  const stddev = Math.sqrt(variance);
  const zScore = stddev > 0 ? (current - mean) / stddev : (current === mean ? 0 : 10);

  const lastTimestamp = new Date(readings[readings.length - 1].timestamp);
  const hourOfDay = lastTimestamp.getUTCHours();
  const isOffHours = hourOfDay >= config.leakageOffHourStart || hourOfDay < config.leakageOffHourEnd;
  const offHoursWindow = readings.slice(-6).map(r => r.value);
  const offHoursFlowSuspect = isOffHours && offHoursWindow.length === 6 && offHoursWindow.every(v => v >= config.leakageMinFlowThreshold);

  const recentWindow = values.slice(-6);
  const recentMean = recentWindow.reduce((a, b) => a + b, 0) / recentWindow.length;
  const recentVariance = recentWindow.reduce((a, b) => a + Math.pow(b - recentMean, 2), 0) / recentWindow.length;
  const stuckSuspect = recentVariance < config.stuckVarianceThreshold && recentMean > 0;

  const isSpike = zScore >= config.spikeZScoreThreshold;
  const isDrop = zScore <= config.dropZScoreThreshold;

  const anomalyDetected = isSpike || isDrop || offHoursFlowSuspect || stuckSuspect;

  const zComponent = Math.min(Math.abs(zScore) * 8, 60);
  const leakComponent = offHoursFlowSuspect ? 25 : 0;
  const stuckComponent = stuckSuspect ? 15 : 0;
  const anomalyScore = Math.round(Math.min(zComponent + leakComponent + stuckComponent, 100));

  return {
    json: {
      ...config,
      meterId: meter.meterId,
      meterAddress: meter.address || meter.location || 'unknown',
      currentReading: current,
      baselineMean: Math.round(mean * 100) / 100,
      baselineStdDev: Math.round(stddev * 100) / 100,
      zScore: Math.round(zScore * 100) / 100,
      isSpike,
      isDrop,
      offHoursFlowSuspect,
      stuckSuspect,
      anomalyDetected,
      anomalyScore,
      lastReadingTimestamp: readings[readings.length - 1].timestamp
    }
  };
});

return output;

// Turn the raw anomaly signals into a fault category, a severity level, and
// the alert payload downstream systems will consume.
const item = $input.item.json;

let category = 'Abnormal Usage';
let recommendedAction = 'Review the recent usage pattern with the customer/site owner.';

if (item.stuckSuspect) {
  category = 'Equipment Fault';
  recommendedAction = 'Dispatch a technician to inspect the meter - readings show no meaningful variation despite an active baseline, which typically indicates a stuck or malfunctioning meter.';
} else if (item.offHoursFlowSuspect) {
  category = 'Possible Leakage';
  recommendedAction = 'Investigate for a leak or an appliance left running - continuous flow was detected during the configured off-hours window.';
} else if (item.isSpike) {
  category = 'Consumption Spike';
  recommendedAction = 'Confirm with the site whether a new high-draw appliance or process was added; rule out meter tampering if unexplained.';
} else if (item.isDrop) {
  category = 'Consumption Drop';
  recommendedAction = 'Verify the meter is still transmitting correctly and that supply has not been interrupted.';
}

let severity = 'Info';
if (item.anomalyScore >= item.criticalScoreThreshold) {
  severity = 'Critical';
} else if (item.anomalyScore >= 40) {
  severity = 'Warning';
}

const alertTitle = `${category}: Meter ${item.meterId} (${item.meterAddress})`;
const alertDescription = `Meter ${item.meterId} at ${item.meterAddress} shows a ${category.toLowerCase()} `
  + `(anomaly score ${item.anomalyScore}/100, z-score ${item.zScore}). Current reading: ${item.currentReading}, `
  + `baseline mean: ${item.baselineMean} +/- ${item.baselineStdDev}. Last reading at ${item.lastReadingTimestamp}.`;

return {
  json: {
    ...item,
    anomalyCategory: category,
    severity,
    alertTitle,
    alertDescription,
    recommendedAction
  }
};
